{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--earth-1:#5a3a2a;--earth-2:#b98f6b;--earth-3:#efe6de;--accent:#7aa374;--muted:#6b6b6b}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial}
    body{background:linear-gradient(180deg,var(--earth-3) 0%, #fff 100%);color:#2b2b2b}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;background:rgba(90,58,42,0.06);border-bottom:1px solid rgba(90,58,42,0.06)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--earth-1),var(--earth-2));display:flex;align-items:center;justify-content:center;color:var(--earth-3);font-weight:700}
    .nav a{margin:0 8px;color:var(--earth-1);text-decoration:none;font-weight:600}
    .nav .links{display:flex;gap:6px;align-items:center}
    .container{max-width:1100px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start}
    .card{background:#fff;padding:22px;border-radius:12px;box-shadow:0 6px 20px rgba(30,20,15,0.06)}
    h1{margin:0 0 8px;font-size:28px;color:var(--earth-1)}
    p.lead{margin:0 0 18px;color:var(--muted)}
    .pricing-grid{display:flex;gap:16px}
    .package{flex:1;padding:18px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbf8f6);border:1px solid rgba(90,58,42,0.06)}
    .package h3{margin:0 0 6px;color:var(--earth-1)}
    .price{font-size:24px;font-weight:700;color:var(--earth-2);margin:6px 0}
    .btn{display:inline-block;padding:10px 14px;border-radius:8px;background:var(--earth-1);color:#fff;text-decoration:none;font-weight:700}
    .muted{color:var(--muted);font-size:14px}
    .small{font-size:13px;color:var(--muted)}
    .grid-2{display:grid;grid-template-columns:1fr 420px;gap:18px;margin-top:18px}
    label{display:block;font-weight:700;margin:8px 0 6px}
    select,input[type=text],textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e4dcd6}
    .blend-output{margin-top:10px;padding:10px;background:#fff9f2;border-radius:8px;border:1px dashed rgba(90,58,42,0.08)}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    footer{padding:24px 0;text-align:center;color:var(--muted);font-size:13px}
    /* subtle SVG pattern as background via asset */
    .pattern{position:absolute;inset:0;opacity:0.06;pointer-events:none;background-image:url('assets/img/pattern.svg');background-repeat:repeat}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header class="nav">
    <div class="brand"><div class="logo">A</div><div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
      <div style="font-size:12px;color:var(--muted)">Seasonal scent planning & bespoke blends</div>
    </div></div>
    <nav class="links">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html" style="opacity:0.9">Pricing</a>
      <a href="about.html">About</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div class="card">
        <h1>Guided sessions and one-day VIP experience</h1>
        <p class="lead">Practical scent work that may support clarity, calm, and renewed attention. Choose focused sessions or a deep VIP Day to design your scent rhythm.</p>
        <div class="pricing-grid">
          <div class="package">
            <h3>60-min Focus Session</h3>
            <div class="price">$160</div>
            <div class="small">An intentional hour: goal-setting, scent selection, a small ritual to practice at home.</div>
            <div style="margin-top:12px"><a class="btn" href="book.html">Reserve</a></div>
          </div>
          <div class="package">
            <h3>Mini Series — 3x 45-min</h3>
            <div class="price">$420</div>
            <div class="small">Short weekly sessions to build a scent routine and a take-home blend.</div>
            <div style="margin-top:12px"><a class="btn" href="book.html">Start a series</a></div>
          </div>
          <div class="package">
            <h3>VIP Day — Sensory Design</h3>
            <div class="price">$1,200</div>
            <div class="small">A focused day: bespoke blends, environment mapping, and a personalized plan to integrate scent into a weekly rhythm.</div>
            <div style="margin-top:12px"><a class="btn" href="book.html">Plan a VIP Day</a></div>
          </div>
        </div>
        <p class="note">All sessions include a short safety briefing. No medical claims — scent work may support wellbeing in simple, practical ways.</p>
      </div>

      <aside class="card">
        <h3 style="margin-top:0">Add-on: Blend Builder</h3>
        <p class="small">Create a simple 10–30 ml blend card and a safe dilution guide. Use this for personal, non-medical scent support.</p>
        <div>
          <label for="vibe">Choose a vibe</label>
          <select id="vibe">
            <option value="calm">Calm & Grounding</option>
            <option value="clarity">Clarity & Focus</option>
            <option value="lift">Gentle Uplift</option>
            <option value="rest">Evening Rest</option>
          </select>
          <label for="size">Blend size</label>
          <select id="size">
            <option value="10">10 ml</option>
            <option value="15">15 ml</option>
            <option value="30">30 ml</option>
          </select>
          <label for="population">Who is it for?</label>
          <select id="population">
            <option value="adult">Adult (18+)</option>
            <option value="pregnancy">Pregnant/Breastfeeding — consult</option>
            <option value="child">Child (6–12) — lower dilution</option>
            <option value="pet">Household with pets — caution</option>
          </select>
          <div class="blend-output" id="blendCard" aria-live="polite">
            <strong>Blend card will appear here.</strong>
          </div>
          <div style="margin-top:10px"><button class="btn" id="copyBlend">Copy blend text</button></div>
          <p class="note">Safety first: always patch test, keep essential oils away from eyes and mucous membranes, and follow the dilution guidance provided.</p>
        </div>
      </aside>
    </section>

    <section style="margin-top:20px" class="card">
      <h3 style="margin-top:0">How we bill</h3>
      <p class="small">Sessions are priced per meeting. The VIP Day is billed as a full-day creative and practical session with a planning packet and a set of bespoke blends. Travel and materials may be added for in-person VIP Days.</p>
      <div style="display:flex;gap:12px;margin-top:12px;flex-wrap:wrap">
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid rgba(90,58,42,0.04);flex:1">
          <strong>Deposit</strong>
          <div class="small">A 30% deposit reserves your VIP Day date. Balance due two weeks prior.</div>
        </div>
        <div style="padding:12px;border-radius:10px;background:#fff;border:1px solid rgba(90,58,42,0.04);flex:1">
          <strong>Cancellation</strong>
          <div class="small">Reschedule within 72 hours for a partial credit; cancellations within 14 days may forfeit deposit for VIP Day.</div>
        </div>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • {{PHONE}}</div>
  </footer>

  <script>
    // Blend builder logic
    function percent(totalDrops, drops){return Math.round((drops/totalDrops)*100*10)/10}
    const vibes = {
      calm: {notes:['Vetiver','Lavender','Frankincense'],ratio:[2,3,1],intention:'Grounding and gentle settle'},
      clarity: {notes:['Rosemary','Bergamot','Peppermint'],ratio:[2,2,1],intention:'Crisp focus without overstimulation'},
      lift: {notes:['Sweet Orange','Grapefruit','Geranium'],ratio:[3,2,1],intention:'Bright, gentle uplift'},
      rest: {notes:['Roman Chamomile','Lavender','Cedarwood'],ratio:[2,3,1],intention:'Wind-down blend for evening ritual'}
    };

    function computeBlend(){
      const vibeKey = document.getElementById('vibe').value;
      const size = parseInt(document.getElementById('size').value,10); // ml
      const population = document.getElementById('population').value;

      // typical drop count per ml ~20
      const dropsPerMl = 20;
      const totalDrops = size * dropsPerMl;

      const base = vibes[vibeKey];
      const totalRatio = base.ratio.reduce((a,b)=>a+b,0);
      const dropCounts = base.ratio.map(r=>Math.round((r/totalRatio)*totalDrops));

      // dilution guidance (safety-forward)
      let dilution; let notesample;
      if(population==='adult'){
        dilution = 'Recommended dilution: 1–3% for topical use. For a '+size+'ml bottle, 1% ≈ '+Math.round(totalDrops*0.01)+' drops; 3% ≈ '+Math.round(totalDrops*0.03)+' drops.';
      } else if(population==='child'){
        dilution = 'For children (6–12): reduce to 0.25–1%. For a '+size+'ml bottle, 0.5% ≈ '+Math.round(totalDrops*0.005)+' drops. Always consult a practitioner and patch test.';
      } else if(population==='pregnancy'){
        dilution = 'Pregnancy/breastfeeding: many oils are best avoided. Consult a qualified practitioner before use. If approved, use very low dilutions (0.25–0.5%).';
      } else {
        dilution = 'Households with pets: avoid direct topical application to pets and use very low ambient levels; check each oil for pet safety.';
      }

      let blendText = 'Blend card — '+(vibeKey.charAt(0).toUpperCase()+vibeKey.slice(1))+" ("+size+" ml)\n";
      blendText += 'Intention: '+base.intention+'\n\n';
      blendText += 'Formula (approx. drops):\n';
      base.notes.forEach((n,i)=>{blendText += '- '+n+': '+dropCounts[i]+' drops ('+percent(totalDrops,dropCounts[i])+'%)\n'});
      blendText += '\nCarrier: Fractionated coconut oil or jojoba to fill to '+size+' ml.\n'+dilution+'\n\nSafety: Patch test on a small skin area; avoid eyes; keep out of reach of children. This is non-medical guidance.';

      document.getElementById('blendCard').innerText = blendText;
    }

    document.getElementById('vibe').addEventListener('change',computeBlend);
    document.getElementById('size').addEventListener('change',computeBlend);
    document.getElementById('population').addEventListener('change',computeBlend);
    document.getElementById('copyBlend').addEventListener('click',function(){
      const t = document.getElementById('blendCard').innerText;
      navigator.clipboard && navigator.clipboard.writeText(t);
      this.innerText = 'Copied';
      setTimeout(()=>this.innerText='Copy blend text',1200);
    });

    // initialize
    computeBlend();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--earth-1:#5a3a2a;--accent:#7aa374;--bg:#fbf7f3;--muted:#6d6d6d}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:var(--bg);color:#2b2b2b}
    .wrap{max-width:960px;margin:32px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center;padding-bottom:12px}
    .nav a{margin-left:10px;color:var(--earth-1);text-decoration:none;font-weight:700}
    .intro{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(30,20,15,0.04)}
    h1{margin:0 0 6px;color:var(--earth-1)}
    .muted{color:var(--muted)}
    .process{display:flex;gap:12px;margin-top:14px}
    .step{flex:1;padding:12px;border-radius:8px;background:linear-gradient(180deg,#fff,#fcf8f5);border:1px solid rgba(90,58,42,0.04)}
    .cta{margin-top:14px}
    .btn{background:var(--earth-1);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    .faq{margin-top:18px}
    details{margin-bottom:8px}
    .pattern{position:absolute;left:0;top:0;opacity:0.05;pointer-events:none;width:100%;height:100%;background-image:url('assets/img/pattern.svg');background-repeat:repeat}
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <div class="wrap">
    <header>
      <div style="display:flex;gap:12px;align-items:center">
        <div style="width:44px;height:44px;background:linear-gradient(135deg,#5a3a2a,#b98f6b);border-radius:8px;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800">A</div>
        <div>
          <div style="font-weight:800">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">Personalized scent plans and blend crafting</div>
        </div>
      </div>
      <nav class="nav">
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="pricing.html">Pricing</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main>
      <section class="intro">
        <div class="card">
          <h1>Why we work with scent</h1>
          <p class="muted">A practical, safety-minded approach to scent. We combine evidence-aware aromatherapy practice with design-minded rituals to help you make scent a usable part of a day. Our work may support calm, focus, and rest — described as possibilities rather than guarantees.</p>

          <div class="process">
            <div class="step">
              <strong>1. Listen</strong>
              <p class="muted">We begin with a short conversation about goals, environment, and preferences.</p>
            </div>
            <div class="step">
              <strong>2. Design</strong>
              <p class="muted">Select scents and craft a simple ritual and blend that fits your routine.</p>
            </div>
            <div class="step">
              <strong>3. Practice</strong>
              <p class="muted">You receive a clear plan, a small blend, and follow-up notes to practice safely at home.</p>
            </div>
          </div>

          <div class="cta">
            <a class="btn" href="book.html">Start a plan</a>
          </div>
        </div>

        <aside class="card">
          <h3 style="margin-top:0">Our commitments</h3>
          <ul class="muted" style="padding-left:16px">
            <li>Safety-forward guidance and clear dilution instructions</li>
            <li>Non-medical, person-centered suggestions</li>
            <li>Respect for scent sensitivities and pets</li>
          </ul>
          <h4 style="margin-top:12px">Values</h4>
          <p class="muted">We favor approachable, repeatable practices that fit into busy routines. The goal is small, reliable adjustments, not grand promises.</p>
        </aside>
      </section>

      <section class="card" style="margin-top:18px">
        <h3 style="margin-top:0">Who leads sessions</h3>
        <p class="muted">Sessions are led by a certified aromatherapy practitioner with experience in scent composition and client-centered planning. Local in {{CITY}}, serving nearby areas of {{STATE}}.</p>
        <div style="display:flex;gap:10px;margin-top:12px;align-items:center">
          <div style="width:84px;height:84px;border-radius:8px;background:linear-gradient(135deg,#b98f6b,#efe6de);display:flex;align-items:center;justify-content:center;font-weight:700;color:#5a3a2a">AC</div>
          <div>
            <div style="font-weight:800">Alex C — Practitioner</div>
            <div class="muted">Background in scent composition, safety-training, and client-centered planning.</div>
          </div>
        </div>
      </section>

      <section class="card faq">
        <h3 style="margin-top:0">FAQ — Safety & practical notes</h3>
        <details>
          <summary>How do you recommend diluting blends?</summary>
          <div class="muted" style="margin-top:8px">Typical adult topical dilutions range from 1–3%. For children, pregnancy, or sensitive people we recommend much lower dilutions (0.25–1%). We always provide a drops-based guide on blend cards and encourage patch testing.</div>
        </details>
        <details>
          <summary>What about pets?</summary>
          <div class="muted" style="margin-top:8px">Some essential oils can be harmful to pets. We avoid recommending direct application to animals and provide pet-safe alternatives and ambient guidance when relevant. Always consult your veterinarian for specific concerns.</div>
        </details>
        <details>
          <summary>Is aromatherapy a medical treatment?</summary>
          <div class="muted" style="margin-top:8px">No. Our guidance is non-medical and meant to support simple day-to-day practices. If you have health concerns, consult a medical professional.</div>
        </details>
      </section>

    </main>

    <footer style="margin-top:18px;text-align:center;color:var(--muted)">
      <div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </footer>
  </div>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--earth-1:#5a3a2a;--accent:#7aa374;--muted:#6d6d6d}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:#fff;color:#222}
    .nav{display:flex;justify-content:space-between;align-items:center;padding:14px 20px;border-bottom:1px solid rgba(90,58,42,0.06)}
    .nav a{margin-left:12px;color:var(--earth-1);text-decoration:none;font-weight:700}
    .wrap{max-width:1100px;margin:28px auto;padding:0 20px}
    h1{color:var(--earth-1)}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:18px;align-items:start}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(30,20,15,0.04)}
    label{display:block;font-weight:700;margin:10px 0 6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e9e3df}
    .btn{background:var(--earth-1);color:#fff;padding:10px 14px;border-radius:8px;border:0;cursor:pointer;font-weight:800}
    .secondary{background:#f6f4f2;border:1px solid rgba(90,58,42,0.04)}
    .muted{color:var(--muted);font-size:14px}
    .session-summary{white-space:pre-wrap;background:#fff8f2;border-radius:8px;padding:12px;border:1px dashed rgba(90,58,42,0.06);min-height:120px}
  </style>
</head>
<body>
  <header class="nav">
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;background:linear-gradient(135deg,#5a3a2a,#b98f6b);border-radius:8px;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800">A</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Pricing</a>
      <a href="about.html">About</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Book and build a small plan</h1>
    <p class="muted">Use the Session Planner to build a short, practical plan for a meeting. The planner creates a plaintext summary you can copy and paste into an email or your notes.</p>

    <div class="grid">
      <section class="card">
        <h2 style="margin-top:0">Session Planner</h2>
        <label for="clientName">Your name</label>
        <input id="clientName" placeholder="First & last">

        <label for="sessionType">Session style</label>
        <select id="sessionType">
          <option value="60min">60-minute session</option>
          <option value="45min">45-minute check-in</option>
          <option value="vip">VIP Day — sensory design</option>
        </select>

        <label for="goal">Primary goal</label>
        <select id="goal">
          <option value="calm">Reduce stress/reactivity</option>
          <option value="focus">Improve focus for work</option>
          <option value="sleep">Support evening wind-down</option>
          <option value="routine">Create a small scent routine</option>
        </select>

        <label for="habits">Current routine & notes</label>
        <textarea id="habits" rows="4" placeholder="Describe your daily rhythm, scent sensitivities, pets, pregnancy, etc."></textarea>

        <div style="display:flex;gap:10px;margin-top:12px;align-items:center">
          <button class="btn" id="buildPlan">Generate plan</button>
          <button class="secondary" id="clearPlan">Clear</button>
        </div>

        <div style="margin-top:12px">
          <label>Plan summary</label>
          <div class="session-summary" id="planSummary">Your personalized plan will appear here after generation.</div>
          <div style="display:flex;gap:8px;margin-top:8px"><button class="btn" id="copyPlan">Copy plan</button><a class="secondary" id="emailPlan" href="#" style="padding:10px 12px;border-radius:8px;text-decoration:none;color:inherit">Email booking</a></div>
        </div>

        <p class="muted" style="margin-top:12px">The planner creates a concise, non-medical plan and safety notes. Always patch test and consult a professional for health concerns.</p>
      </section>

      <aside class="card">
        <h3 style="margin-top:0">Mini blend builder</h3>
        <p class="muted">Select a vibe and size. The builder returns a drop-based formula and a dilution note you can include in your plan.</p>
        <label for="vibe2">Vibe</label>
        <select id="vibe2">
          <option value="calm">Calm</option>
          <option value="clarity">Clarity</option>
          <option value="lift">Uplift</option>
          <option value="rest">Rest</option>
        </select>
        <label for="size2">Size</label>
        <select id="size2">
          <option value="10">10 ml</option>
          <option value="15">15 ml</option>
        </select>
        <label for="audience2">Audience</label>
        <select id="audience2">
          <option value="adult">Adult</option>
          <option value="child">Child</option>
          <option value="pet">With pets</option>
        </select>
        <div style="margin-top:10px">
          <div class="session-summary" id="blendMini">Select options to see a blend card.</div>
          <div style="display:flex;gap:8px;margin-top:8px"><button class="btn" id="insertBlend">Insert into plan</button><button class="secondary" id="copyBlendMini">Copy</button></div>
        </div>

        <hr style="margin:12px 0">
        <h4 style="margin:0">Confirm booking</h4>
        <p class="muted">Complete the booking email or call to confirm a time. Deposits may apply for VIP Days.</p>
        <a class="btn" href="mailto:{{EMAIL}}?subject=Booking%20Request%20from%20Website">Contact to Book</a>
      </aside>
    </div>

    <section style="margin-top:18px" class="card">
      <h3 style="margin-top:0">What happens next</h3>
      <ol class="muted">
        <li>We review the planner notes and propose available times.</li>
        <li>Before the session you'll receive a short intake and safety checklist.</li>
        <li>After the session you'll receive a plan summary and any blend cards made together.</li>
      </ol>
    </section>

    <section style="margin-top:12px" class="card">
      <h3 style="margin-top:0">Quick FAQ</h3>
      <div class="muted">
        <strong>Patch test:</strong> Always test a small amount on inner forearm and wait 24 hours for irritation.\n
        <strong>Pregnancy & medications:</strong> Tell us in the planner notes; we will adjust recommendations and suggest consultation where appropriate.\n
        <strong>Pets:</strong> We'll avoid recommending oils that are unsafe around animals and provide alternatives.
      </div>
    </section>

  </main>

  <script>
    // Session Planner
    function buildPlanText(){
      const name = document.getElementById('clientName').value || 'Client';
      const type = document.getElementById('sessionType').value;
      const goal = document.getElementById('goal').value;
      const habits = document.getElementById('habits').value || 'No notes provided.';

      const typeLabel = { '60min':'60-minute session', '45min':'45-minute check-in', 'vip':'VIP Day — sensory design' }[type];
      const goalLabel = { 'calm':'Reduce stress/reactivity', 'focus':'Improve focus for work', 'sleep':'Support evening wind-down', 'routine':'Create a small scent routine' }[goal];

      let summary = '';
      summary += name + '\n';
      summary += typeLabel + ' — ' + goalLabel + '\n\n';
      summary += 'Notes:\n' + habits + '\n\n';
      summary += 'Suggested session agenda:\n- Brief intake and safety check\n- Scent selection and small practice\n- Blend recipe and at-home routine (drops-based)\n- Follow-up notes\n\n';
      summary += 'Safety: Non-medical suggestions. Patch test before topical use. Consult a professional for health conditions.';
      return summary;
    }

    document.getElementById('buildPlan').addEventListener('click',function(){
      const t = buildPlanText();
      document.getElementById('planSummary').innerText = t;
      document.getElementById('emailPlan').setAttribute('href','mailto:'+encodeURIComponent('{{EMAIL}}')+'?subject='+encodeURIComponent('Booking%20Request%20from%20'+(document.getElementById('clientName').value||'Client'))+'&body='+encodeURIComponent(t));
    });

    document.getElementById('clearPlan').addEventListener('click',function(){
      document.getElementById('clientName').value='';
      document.getElementById('habits').value='';
      document.getElementById('planSummary').innerText='Your personalized plan will appear here after generation.';
    });

    document.getElementById('copyPlan').addEventListener('click',function(){
      const text = document.getElementById('planSummary').innerText;
      navigator.clipboard && navigator.clipboard.writeText(text);
      this.innerText='Copied';setTimeout(()=>this.innerText='Copy plan',1200);
    });

    // Mini blend builder (re-uses simplified rules)
    const miniVibes = {
      calm:['Lavender','Vetiver','Frankincense'],
      clarity:['Rosemary','Bergamot','Peppermint'],
      lift:['Sweet Orange','Grapefruit','Geranium'],
      rest:['Roman Chamomile','Lavender','Cedarwood']
    };
    function computeMini(){
      const v = document.getElementById('vibe2').value;
      const s = parseInt(document.getElementById('size2').value,10);
      const a = document.getElementById('audience2').value;
      const dropsPerMl = 20; const totalDrops = s * dropsPerMl;
      const notes = miniVibes[v];
      const dropCounts = [Math.round(totalDrops*0.45),Math.round(totalDrops*0.35),Math.round(totalDrops*0.2)];
      let dilutionMsg = '';
      if(a==='adult') dilutionMsg='Suggested dilution: 1–3% (drops shown approximate).';
      else if(a==='child') dilutionMsg='Suggested dilution: 0.25–1% — use very low amounts and consult guidance.';
      else dilutionMsg='Pet-safe caution: avoid direct use on animals; use in small ambient amounts and choose pet-safer oils.';

      let text = v.charAt(0).toUpperCase()+v.slice(1)+' — '+s+' ml\nIntention: simple at-home support\n\nFormula:\n';
      notes.forEach((n,i)=>text += '- '+n+': '+dropCounts[i]+' drops\n');
      text += '\nCarrier to fill to '+s+' ml. '+dilutionMsg+'\nSafety: Patch test; avoid eyes; keep away from children.';
      document.getElementById('blendMini').innerText = text;
    }
    document.getElementById('vibe2').addEventListener('change',computeMini);
    document.getElementById('size2').addEventListener('change',computeMini);
    document.getElementById('audience2').addEventListener('change',computeMini);
    computeMini();

    document.getElementById('copyBlendMini').addEventListener('click',function(){
      const t = document.getElementById('blendMini').innerText; navigator.clipboard && navigator.clipboard.writeText(t);
      this.innerText='Copied'; setTimeout(()=>this.innerText='Copy',1200);
    });

    document.getElementById('insertBlend').addEventListener('click',function(){
      const blend = document.getElementById('blendMini').innerText;
      const cur = document.getElementById('planSummary').innerText;
      document.getElementById('planSummary').innerText = cur + '\n\nBlend included:\n' + blend;
    });
  </script>
</body>
</html>"} 
